style.css:
@-moz-document domain("roblox.com") {
.profile-avatar-left .enable-three-dee {
        background-color: #000000;
        color: #ffffff;
    }
    .dark-theme #catalog-react-page .search-bars {
        background: #000000;
    }
    #topic-carousel {
        background-color: rgb(11, 11, 11);
    }
    .dark-theme .topic-container .topic-carousel .unselected-topic {
        background-color: hsl(0deg 0% 10.38%);
        color: #bdbebe;
    }
    .dark-theme .btn-generic-slideshow-xs {
        background-color: rgba(0, 0, 0, 0.3);
        border-color: rgba(219, 219, 219, 0.7);
    }
    .dark-theme .btn-generic-grid-xs {
        background-color: rgba(0, 0, 0, 0.3);
        border-color: rgba(255, 255, 255, 0.7);
    }
    .dark-theme .btn-growth-md {
        background-color: #000000;
        border-color: #ffffff;
        color: #fff;
        border-radius: 8px;
    }
    .dark-theme .btn-alert-md {
        background-color: transparent;
        border-color: #4f191b;
        color: #ab363b;
        border-radius: 8px;
    }
    #reputationDiv {
        filter: grayscale(1);
    }
    .btr-profile #roblox-badges-container .badge-list > .list-item .asset-thumb-container {
        margin-left: 5px;
        transform: scale(0.642857);
        transform-origin: 0 0;
        margin-bottom: -50px;
        filter: grayscale(1) contrast(1.2) brightness(.2);
    }
    .dark-theme.btr-profile .btr-games-list .btr-game-button {
        background-color: #101010;
        border-color: #101010;
    }
    .chat-container .chat-main .chat-header {
        background-color: #0e0e0e;
    }
    .chat-main {
        box-shadow: 0 0px 0px;
    }
    .rbx-divider {
        height: 0;
        background-color: #00000000;
        overflow: hidden;
    }
    .dark-theme .chat-main {
        background-color: #000000;
        color: #fff;
    }
    .dark-theme .rbx-left-col {
        box-shadow: 0 0 8px 0 rgba(0, 0, 0, 0.3);
        background-color: #000000;
    }
    .dark-theme .rbx-header {
        background-color: #000000;
        border: solid #1a1a1a;
        border-width: 0 0 0px;
    }
    .dark-theme .menu-vertical {
        background-color: #080808;
        color: #fff;
    }
    .dark-theme .content {
        background-color: rgba(0, 0, 0, 0);
        color: #fff;
        border-radius: 5px;
    }
    .dark-theme .section-content {
        background-color: rgba(0, 0, 0, 0.45);
        color: #fff;
        border-radius: 5px;
    }
    .dark-theme .stack .stack-list .stack-row {
        background-color: rgba(0, 0, 0, 0.45);
        color: #fff;
        border-radius: 5px;
    }
    .dark-theme .stack .card-list .card-item {
        background-color: transparent;
        border-radius: 5px;
    }
    .dark-theme .rbx-tab .rbx-tab-heading {
        background-color: rgba(0, 0, 0, 0);
        color: #fff;
        border-radius: 5px;
    }
    .dark-theme .rbx-tabs-horizontal .nav-tabs {
        background-color: rgba(0, 0, 0, 0.71);
        color: #fff;
        border-radius: 5px;
    }
    .dark-theme {
        background-color: rgba(0, 0, 0, 0);
        color: #fff;
    }
    .dark-theme .rbx-tabs-vertical .category-tabs .menu-vertical {
        background-color: rgba(0, 0, 0, 0.51);
        color: #fff;
        border-radius: 5px;
    }
    .dark-theme .asset-thumb-container {
        background-color: rgba(0, 0, 0, 0.28);
        border: 0;
    }
    .dark-theme .thumbnail-2d-container {
        border: 0;
        background-color: rgba(0, 0, 0, 0.39);
        border-color: #393b3d;
    }
    .dark-theme {
        background-color: #000000;
        color: #fff;
        background-size: 100% 100%;
    }
}
